# Generated by Devin — backfill academic_year on QuarterGrade/QuarterLock.
#
# Attribution rules (deterministic, no guessing from class names):
#
#   QuarterLock   -> the academic year containing its own locked_at date.
#                    A lock always froze the year it was created in; this
#                    keeps currently-frozen values protected and never
#                    extends a legacy lock into an unrelated future year.
#
#   QuarterGrade  -> quarters 1-4 are derived aggregates of the source
#                    Grade rows. A stored row is stamped with a year only
#                    when EVERY supporting source row for that
#                    (student, subject, quarter) is attributed to exactly
#                    ONE academic year — the same attribution the runtime
#                    uses (linked rows follow the assessment's date +
#                    quarter; unlinked rows follow their own date). Rows
#                    with zero or multi-year support, and quarter=0
#                    attestation rows (teacher-entered, no source
#                    evidence), keep academic_year=NULL: genuinely
#                    ambiguous, preserved as legacy for the read-only
#                    audit to flag for manual attribution.
#
# No row is deleted, relabeled, or given an assumed year.
# Reverse is a noop: unapplying is not supported — restore a backup.
from collections import defaultdict

from django.db import migrations
from django.utils import timezone

SOURCE_PERIOD = 'Холҳои ҷорӣ (Онлайн)'
QUARTERS = (1, 2, 3, 4)
BATCH = 2000


def _ay_start(d):
    """September-start academic year containing date d."""
    return d.year if d.month >= 9 else d.year - 1


def _date_quarter(d):
    if d.month in (9, 10, 11):
        return 1
    if d.month in (12, 1, 2):
        return 2
    if d.month in (3, 4, 5):
        return 3
    if d.month in (6, 7, 8):
        return 4
    return None


def backfill_academic_year(apps, schema_editor):
    QuarterGrade = apps.get_model('portal', 'QuarterGrade')
    QuarterLock = apps.get_model('portal', 'QuarterLock')
    Grade = apps.get_model('portal', 'Grade')

    # Locks: the year containing their own locked_at timestamp.
    locks = []
    for lock in QuarterLock.objects.filter(
            academic_year__isnull=True).iterator():
        if lock.locked_at is None:
            continue  # no evidence at all — leave NULL for review
        lock.academic_year = _ay_start(timezone.localdate(lock.locked_at))
        locks.append(lock)
        if len(locks) >= BATCH:
            QuarterLock.objects.bulk_update(locks, ['academic_year'])
            locks = []
    if locks:
        QuarterLock.objects.bulk_update(locks, ['academic_year'])

    # Support map: (student_id, subject, quarter) -> set of academic
    # years the existing source rows are attributed to. Grade.subject and
    # QuarterGrade.subject are both normalized by save(), so raw string
    # keys match.
    support = defaultdict(set)
    for sid, subj, d, a_q, a_d in Grade.objects.filter(
            period=SOURCE_PERIOD, score__isnull=False,
    ).values_list(
            'student_id', 'subject', 'date',
            'assessment__quarter', 'assessment__date').iterator(
            chunk_size=5000):
        if a_q in QUARTERS and a_d is not None:
            q, y = a_q, _ay_start(a_d)
        else:
            q, y = _date_quarter(d), _ay_start(d)
        if q in QUARTERS:
            support[(sid, subj, q)].add(y)

    updates = []
    for qg in QuarterGrade.objects.filter(
            academic_year__isnull=True).iterator(chunk_size=2000):
        if qg.quarter in QUARTERS:
            years = support.get((qg.student_id, qg.subject, qg.quarter))
            if years is not None and len(years) == 1:
                qg.academic_year = next(iter(years))
                updates.append(qg)
        # quarter=0 attestation rows and cells with zero/multi-year
        # support stay NULL — ambiguous, flagged by the audit.
        if len(updates) >= BATCH:
            QuarterGrade.objects.bulk_update(updates, ['academic_year'])
            updates = []
    if updates:
        QuarterGrade.objects.bulk_update(updates, ['academic_year'])


class Migration(migrations.Migration):

    dependencies = [
        ('portal', '0025_alter_quartergrade_unique_together_and_more'),
    ]

    operations = [
        migrations.RunPython(
            backfill_academic_year,
            migrations.RunPython.noop,
        ),
    ]
